import json

import config
import database


def load_taxonomy(path=config.TAXONOMY_FILE):
    """Read the committed taxonomy and validate its stable identifiers."""
    taxonomy = json.loads(path.read_text(encoding='utf-8'))
    validate_taxonomy(taxonomy)
    return taxonomy


def validate_taxonomy(taxonomy):
    """Require three directions, unique keys and one Other bundle per direction."""
    try:
        directions = [row['key'] for row in taxonomy['directions']]
        if len(directions) != 3 or set(directions) != set(config.DIRECTION_COLORS):
            raise ValueError('Taxonomy must contain Sports, Leisure and Career exactly once.')
        keys, counts = set(directions), dict.fromkeys(directions, 0)
        for bundle in taxonomy['bundles']:
            if bundle['key'] in keys or bundle['direction'] not in counts:
                raise ValueError('Invalid or duplicate taxonomy key.')
            keys.add(bundle['key'])
            if bundle['is_other']:
                counts[bundle['direction']] += 1
        if any(count != 1 for count in counts.values()):
            raise ValueError('Each direction needs exactly one Other bundle.')
    except (KeyError, TypeError) as error:
        raise ValueError('Invalid taxonomy structure.') from error


def seed_categories(connection, taxonomy):
    """Seed categories without renaming keys or silently changing a frozen version."""
    validate_taxonomy(taxonomy)
    saved = database.get_setting(connection, 'taxonomy_version')
    if saved is not None and saved != str(taxonomy['_meta']['version']):
        raise ValueError('Taxonomy version changed. Review before resetting demo data.')
    database.seed_taxonomy(connection, taxonomy)


def normalize_text(text):
    """Normalize Unicode letters/digits into lowercase space-separated words."""
    # Course: U03 s1 – a simple loop makes text normalization easy to study.
    letters = []
    for character in str(text).lower():
        letters.append(character if character.isalnum() else ' ')
    return ' '.join(''.join(letters).split())


def keyword_matches(keyword, words, text):
    """Match whole words, simple plurals and bounded multiword phrases."""
    keyword = normalize_text(keyword)
    if ' ' in keyword:
        return f' {keyword} ' in f' {text} '
    return keyword in words or keyword + 's' in words or keyword + 'es' in words


def bundle_score(bundle, title, description):
    """Score title matches twice and description matches once (SPEC section 8.3)."""
    title, description = normalize_text(title), normalize_text(description)
    title_words, description_words = set(title.split()), set(description.split())
    score = 0
    for keyword in bundle['keywords']:
        if keyword_matches(keyword, title_words, title):
            score += config.TITLE_KEYWORD_WEIGHT
        if keyword_matches(keyword, description_words, description):
            score += config.DESCRIPTION_KEYWORD_WEIGHT
    return score


def _best_bundle(bundles, record):
    """Choose the highest positive score, breaking ties by taxonomy order."""
    best, best_score = None, 0
    for bundle in sorted(bundles, key=lambda row: row['sort_order']):
        score = bundle_score(bundle, record['title'], record.get('description', ''))
        if score > best_score:
            best, best_score = bundle, score
    return best


def assign_category(record, taxonomy):
    """Return deterministic (direction_key, bundle_key) using the specified precedence."""
    event_type = record.get('event_type', '')
    if record['source'] == 'unisport':
        direction = 'sports'
    else:
        direction = taxonomy['event_type_to_direction'].get(event_type)
        if direction is None:
            direction = taxonomy['club_category_to_direction'].get(record.get('club_category'))
        if direction is None:
            best = _best_bundle(taxonomy['bundles'], record)
            direction = best['direction'] if best else 'leisure'
    bundles = [row for row in taxonomy['bundles'] if row['direction'] == direction]
    mapped = taxonomy['event_type_to_bundle'].get(event_type)
    for bundle in bundles:
        if bundle['key'] == mapped:
            return direction, mapped
    best = _best_bundle(bundles, record)
    if best is None:
        best = next(row for row in bundles if row['is_other'])
    return direction, best['key']


def direction_color(direction_key, kind='streamlit'):
    """Return the configured color for a direction and presentation medium."""
    try:
        return config.DIRECTION_COLORS[direction_key][kind]
    except KeyError as error:
        raise ValueError('Unknown direction or color kind.') from error
